"""Regenerates bench/benchmark_large.py.

Emits N repetitions of several block templates (transformer, GRU/scan,
conv/pool, numpy-ops soup, indexing soup), each with unique class/dim names so
nothing collapses into shared symbols. A few blocks carry deliberate shape
errors (marked `# expected-error`) so the diagnostics path is exercised too.

Run: python3 bench/generate_benchmark.py
"""

from pathlib import Path

HEADER = '''\
# AUTO-GENERATED by bench/generate_benchmark.py -- do not edit by hand.
# Large edge-case-heavy benchmark input for ndim-lsp. Lines marked
# `# expected-error` are deliberate shape mismatches.
import jax
import jax.numpy as jnp
import numpy as np
import equinox as eqx
from jaxtyping import Float, Array


'''

TRANSFORMER = '''\
class TransformerBlock{i}(eqx.Module):
    norm1: eqx.nn.LayerNorm
    norm2: eqx.nn.LayerNorm
    qkv: eqx.nn.Linear
    proj: eqx.nn.Linear
    fc1: eqx.nn.Linear
    fc2: eqx.nn.Linear

    def __init__(self, dm{i}, dff{i}, key):
        self.norm1 = eqx.nn.LayerNorm(dm{i})
        self.norm2 = eqx.nn.LayerNorm(dm{i})
        self.qkv = eqx.nn.Linear(dm{i}, dm{i} * 3, key=key)
        self.proj = eqx.nn.Linear(dm{i}, dm{i}, key=key)
        self.fc1 = eqx.nn.Linear(dm{i}, dff{i}, key=key)
        self.fc2 = eqx.nn.Linear(dff{i}, dm{i}, key=key)

    def __call__(self, x: Float[Array, "seq{i} dm{i}"]):
        h = jax.vmap(self.norm1)(x)
        qkv = jax.vmap(self.qkv)(h)
        q, k, v = jnp.split(qkv, 3, axis=-1)
        scores = q @ jnp.transpose(k)
        attn = jax.nn.softmax(scores, axis=-1)
        ctx = attn @ v
        ctx = jax.vmap(self.proj)(ctx)
        x = x + ctx
        h = jax.vmap(self.norm2)(x)
        h = jax.nn.gelu(jax.vmap(self.fc1)(h))
        h = jax.vmap(self.fc2)(h)
        x = x + h
        return x


'''

GRU = '''\
class GRUCell{i}(eqx.Module):
    wz_x: eqx.nn.Linear
    wz_h: eqx.nn.Linear
    wh_x: eqx.nn.Linear
    wh_h: eqx.nn.Linear

    def __init__(self, isz{i}, hsz{i}, key):
        self.wz_x = eqx.nn.Linear(isz{i}, hsz{i}, key=key)
        self.wz_h = eqx.nn.Linear(hsz{i}, hsz{i}, key=key)
        self.wh_x = eqx.nn.Linear(isz{i}, hsz{i}, key=key)
        self.wh_h = eqx.nn.Linear(hsz{i}, hsz{i}, key=key)

    def step(
        self,
        h: Float[Array, "hsz{i}"],
        x: Float[Array, "isz{i}"],
    ) -> Float[Array, "hsz{i}"]:
        zx = self.wz_x(x)
        zh = self.wz_h(h)
        z = jax.nn.sigmoid(zx + zh)
        hx = self.wh_x(x)
        hh = self.wh_h(h)
        h_tilde = jnp.tanh(hx + hh)
        h_new = (1 - z) * h + z * h_tilde
        return h_new


'''

NUMPY_SOUP = '''\
def numpy_soup_{i}(
    a: Float[Array, "b{i} n{i} d{i}"],
    w: Float[Array, "d{i} k{i}"],
):
    y = a @ w
    flat = y.reshape(-1)
    tot = flat.sum()
    m = jnp.mean(y, axis=1)
    s = jnp.stack([m, m, m])
    c = jnp.concatenate([y, y], axis=1)
    t = jnp.transpose(y, (2, 0, 1))
    e = jnp.expand_dims(m, axis=-1)
    sq = jnp.squeeze(e, axis=-1)
    br = jnp.broadcast_to(sq, (4, "b{i}", "k{i}"))
    ti = jnp.tile(m, (2, 1))
    z = jnp.zeros((3, 5))
    o = jnp.ones_like(y)
    wh = jnp.where(y > 0, y, o)
    p = jnp.pad(z, ((1, 1), (2, 2)))
    cs = jnp.cumsum(y, axis=0)
    st = jnp.vstack([z, z])
    return tot, s, c, t, br, ti, wh, p, cs, st


'''

INDEXING_SOUP = '''\
def indexing_soup_{i}(
    x: Float[Array, "b{i} s{i} h{i} d{i}"],
):
    first = x[0]
    tail = x[:, 1:]
    newax = x[:, None]
    lastd = x[..., 0]
    window = x[:, :16]
    head0 = x[:, :, 0, :]
    b, s, h, d = x.shape
    folded = x.reshape(b, s, -1)
    merged = folded.sum(axis=-1)
    ranked = jnp.argsort(merged, axis=1)
    picked = jnp.take(merged, ranked, axis=1)
    return first, tail, newax, lastd, window, head0, picked


'''

CONV_NET = '''\
class ConvNet{i}(eqx.Module):
    conv1: eqx.nn.Conv2d
    conv2: eqx.nn.Conv2d
    fc: eqx.nn.Linear

    def __init__(self, key):
        self.conv1 = eqx.nn.Conv2d(3, 16, kernel_size=3, key=key)
        self.conv2 = eqx.nn.Conv2d(16, 32, kernel_size=3, key=key)
        self.fc = eqx.nn.Linear(32, 10, key=key)

    def __call__(self, x: Float[Array, "3 hh{i} ww{i}"]):
        h = jax.nn.relu(self.conv1(x))
        h = jax.nn.relu(self.conv2(h))
        pooled = h.mean(axis=(1, 2))
        logits = self.fc(pooled)
        probs = jax.nn.softmax(logits)
        return probs


'''

ERROR_BLOCK = '''\
class BrokenMLP{i}(eqx.Module):
    fc1: eqx.nn.Linear
    fc2: eqx.nn.Linear

    def __init__(self, key):
        self.fc1 = eqx.nn.Linear(128, 64, key=key)
        self.fc2 = eqx.nn.Linear(32, 10, key=key)

    def __call__(self, x: Float[Array, "128"]):
        h = self.fc1(x)
        out = self.fc2(h)  # expected-error: fc2 wants 32, h is 64
        return out


def broken_matmul_{i}(
    a: Float[Array, "m{i} k{i}"],
    b: Float[Array, "j{i} n{i}"],
):
    c = a @ b  # expected-error: inner dims k{i} vs j{i}
    return c


def broken_concat_{i}(
    p: Float[Array, "r{i} c{i}"],
    q: Float[Array, "r{i} e{i}"],
):
    out = jnp.concatenate([p, q], axis=0)  # expected-error: axis-0 concat, trailing dims differ
    return out


'''

BLOCKS = [TRANSFORMER, GRU, NUMPY_SOUP, INDEXING_SOUP, CONV_NET]
REPS = 30          # 30 * 5 templates + errors -> ~4400 lines
ERROR_EVERY = 6    # one error block per 6 repetitions


def main():
    parts = [HEADER]
    for i in range(REPS):
        for tpl in BLOCKS:
            parts.append(tpl.format(i=i))
        if i % ERROR_EVERY == 0:
            parts.append(ERROR_BLOCK.format(i=i))
    out = Path(__file__).parent / "benchmark_large.py"
    text = "".join(parts)
    out.write_text(text)
    print(f"wrote {out} ({len(text.splitlines())} lines)")


if __name__ == "__main__":
    main()
